"""Build the ZedBoard ML-DSA benchmark, or run it against the native HLS model."""
import argparse
import os
from pathlib import Path
import shutil
import subprocess
import zipfile

APP = Path(__file__).resolve().parent
ROOT = APP.parents[1]
REF = ROOT / "third_party/dilithium/ref"
HLS = ROOT / "hw/hls/keccak"
WORK = ROOT / "build/vitis"
BUILD = ROOT / "build/mldsa"
SOURCES = ["sign", "packing", "polyvec", "poly", "ntt", "reduce", "rounding",
           "symmetric-shake"]
# Register headers of v1 and v2 come from their XSA (driver generated by HLS).
V12_XSA = {1: "keccak_f_system.xsa", 2: "keccak_f_system_maxi.xsa"}


def arm_gcc():
    gcc = shutil.which("arm-none-eabi-gcc")
    if gcc:
        return gcc
    xilinx = os.environ.get("XILINX_ROOT")
    if not xilinx:
        raise SystemExit("arm-none-eabi-gcc not found: source scripts/env.sh (needs XILINX_ROOT)")
    return str(Path(xilinx) / "Vitis/gnu/aarch32/lin/gcc-arm-none-eabi/bin/arm-none-eabi-gcc")


def link(args, directory, flags, sources, name):
    bsp = args.bsp.resolve()
    if not (bsp / "include/xparameters.h").is_file():
        raise SystemExit(f"BSP not found in {bsp}: create it with sw/platform/create_platform.py or pass --bsp")
    elf = directory / name
    subprocess.run([arm_gcc(), *flags, "-I", directory, "-I", bsp / "include", "-DSDT",
                    "-mcpu=cortex-a9", "-mfpu=vfpv3", "-mfloat-abi=hard",
                    f"-specs={bsp}/Xilinx.spec", *sources, "-L", bsp / "lib",
                    "-Wl,--defsym,_STACK_SIZE=0x40000", "-T", args.ldscript.resolve(),
                    "-Wl,--start-group,-lxilstandalone,-lxiltimer,-lxil,-lgcc,-lc,--end-group",
                    "-o", elf], check=True)
    print(elf)


def extract_v12_header(version, directory):
    driver = "xkeccak_f1600_hw.h"
    with zipfile.ZipFile(ROOT / "build/xsa" / V12_XSA[version]) as archive:
        (directory / driver).write_bytes(archive.read(
            f"drivers/keccak_f1600_v1_0/src/{driver}"))


def build_keccak_test(args, backend):
    """Single-permutation test of v1 or v2 (sw/keccak_test), as measured on the board."""
    if args.target != "board" or backend not in ("v1", "v2"):
        raise SystemExit("--keccak-test requires board and backend v1 or v2")
    version = int(backend[1])
    directory = BUILD / "keccak-test" / backend
    directory.mkdir(parents=True, exist_ok=True)
    extract_v12_header(version, directory)
    source = ROOT / "sw/keccak_test" / ("v1_axilite/keccak_test.c" if version == 1 else "keccak_test.c")
    link(args, directory, ["-O3", "-I", REF], [source], "keccak_test.elf")


def build(args, backend):
    if args.keccak_test:
        build_keccak_test(args, backend)
        return
    with_ntt = backend.startswith("v3-ntt")
    bidir = backend == "v3-ntt64bi"
    version = 3 if with_ntt else {"sw": 0, "v1": 1, "v2": 2, "v3": 3}[backend]
    # v3-ntt: forward NTT with the 32-bit master (hw/hls/ntt/w32).
    # v3-ntt64: forward NTT with the 64-bit master (hw/hls/ntt/w64).
    # v3-ntt64bi: forward and inverse NTT, 64-bit master (hw/hls/ntt); this
    # ELF runs on both the ntt64bi and the final (HP2) bitstreams.
    ntt_variants = {"v3-ntt": ("ntt/w32", "eight_lane_hls"),
                    "v3-ntt64": ("ntt/w64", "eight_lane_w64_hls"),
                    "v3-ntt64bi": ("ntt", "eight_lane_bidir_hls")}
    directory = BUILD / args.target / f"mode{args.mode}" / backend
    if args.squeeze_profile:
        if args.target != "board" or backend != "v3":
            raise SystemExit("--squeeze-profile requires board v3")
        directory = BUILD / "squeeze-profile"
    directory.mkdir(parents=True, exist_ok=True)
    flags = ["-O3", f"-DMLDSA_BACKEND={version}", f"-DDILITHIUM_MODE={args.mode}",
             "-Drandombytes=mldsa_benchmark_bytes", "-I", APP, "-I", REF, "-I", HLS]
    sources = [APP / "benchmark.c", *(REF / f"{name}.c" for name in SOURCES)]
    if args.squeeze_profile:
        flags.append("-DKECCAK_SQUEEZE_PROFILE")
        sources = [ROOT / "sw/keccak_test/squeeze_profile/profile.c"]
    fips = REF / "fips202.c"
    if version:
        adapted = directory / "fips202.c"
        subprocess.run(["patch", "-s", "-f", "--fuzz=0", "-o", adapted,
                        fips, APP / "fips202.patch"], check=True, cwd=directory)
        fips = adapted
        flags += ["-include", APP / "backend.h"]
    sources.append(fips)
    if with_ntt:
        src, ntt_hls = ntt_variants[backend]
        ntt_src = HLS.parent / src
        flags.append("-DMLDSA_NTT")
        if bidir:
            flags.append("-DNTT_BIDIRECTIONAL")
        adapted = directory / "ntt.c"
        subprocess.run(["patch", "-s", "-f", "--fuzz=0", "-o", adapted,
                        REF / "ntt.c", APP / "ntt.patch"], check=True, cwd=directory)
        sources[sources.index(REF / "ntt.c")] = adapted

    if args.target == "host":
        flags += ["-DHOST_MODEL"]
        objects = []
        if version:
            top = HLS / ("v1_axilite/keccak.cpp" if version == 1 else "keccak.cpp")
            models = [APP / "host_model.cpp", top]
            model_flags = [f"-DMLDSA_BACKEND={version}", "-I", HLS]
            if with_ntt:
                models.append(ntt_src / "ntt_forward.cpp")
                model_flags += ["-DMLDSA_NTT", "-I", ntt_src]
                if bidir:
                    model_flags.append("-DNTT_BIDIRECTIONAL")
            for src in models:
                obj = directory / src.with_suffix(".o").name
                subprocess.run(["c++", "-O3", *model_flags,
                                "-c", src, "-o", obj], check=True)
                objects.append(obj)
        exe = directory / "mldsa"
        subprocess.run(["cc", *flags, *sources, *objects, "-o", exe], check=True)
        subprocess.run([exe], check=True)
        return

    bsp = args.bsp.resolve()
    if version in (1, 2):
        extract_v12_header(version, directory)
    if version == 3:
        header = args.v3_header or bsp / "include/xkeccak_multiblock_hw.h"
        if args.v3_header is None and not header.is_file():
            header = (BUILD / "hls-v3/multiblock/solution/impl/ip/drivers" /
                      "keccak_multiblock_v1_0/src/xkeccak_multiblock_hw.h")
        if not header.is_file():
            raise SystemExit("Pass with --v3-header the xkeccak_multiblock_hw.h generated by HLS.")
        flags += ["-I", header.resolve().parent]
    if version:
        sources.append(APP / "board.c")
    if with_ntt:
        top = "ntt_transform" if bidir else "ntt_forward"
        flags += ["-I", ROOT / "build/ntt" / ntt_hls / f"solution/impl/ip/drivers/{top}_v1_0/src"]
    link(args, directory, flags, sources, "mldsa.elf")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("target", choices=["board", "host"])
    parser.add_argument("backends", nargs="+", choices=["sw", "v1", "v2", "v3", "v3-ntt", "v3-ntt64", "v3-ntt64bi"])
    parser.add_argument("--mode", type=int, choices=[2, 3, 5], default=2,
                        help="2 = ML-DSA-44, 3 = ML-DSA-65, 5 = ML-DSA-87")
    parser.add_argument("--bsp", type=Path, default=WORK /
                        "zedboard_platform/export/zedboard_platform/sw/standalone_ps7_cortexa9_0")
    parser.add_argument("--ldscript", type=Path, default=ROOT / "sw/platform/lscript.ld")
    parser.add_argument("--v3-header", type=Path)
    parser.add_argument("--squeeze-profile", action="store_true",
                        help="build the isolated five-block SHAKE128 profiling ELF")
    parser.add_argument("--keccak-test", action="store_true",
                        help="build the single-permutation test of v1 or v2 (sw/keccak_test)")
    options = parser.parse_args()
    for choice in options.backends:
        build(options, choice)
